import React, { useEffect, useState } from "react";
import io from "socket.io-client";

const backEndUrl = "http://localhost:8000";

const Chat = () => {
    const [user, setUser] = useState("");
    const [room, setRoom] = useState("");
    const [socket, setSocket] = useState(null);
    const [msg,setMsg] = useState("");
    const [messages, setMessages] = useState([]);

    useEffect(() => {
        const searchParams = new URLSearchParams(window.location.search);
        const name = searchParams.get("name")?.trim() || "Anonymous"; 
        const roomParam = searchParams.get("room")?.trim() || "General"; 

        console.log("User:", name, "Room:", roomParam);
        setUser(name);
        setRoom(roomParam);

        const newSocket = io(backEndUrl, { transports: ["websocket"], reconnection: true });

        newSocket.on("connect", () => {
            console.log("Connected to server");

            newSocket.emit("joinRoom", { name, room: roomParam }, (response) => {
                if (response?.error) {
                    console.error("Join Room Error:", response.error);
                } else {
                    console.log("Joined Room Successfully");
                }
            });
        });

        setSocket(newSocket);

        return () => {
            newSocket.disconnect(); 
        };
    }, []);

    useEffect(() => {
        if (!socket) return;

        const messageListener = (msg) => {
            setMessages((prevMessages) => [...prevMessages, msg]);
        };

        socket.on("message", messageListener);

        return () => {
            socket.off("message", messageListener);
        };
    }, [socket]);

    return (
        <div>
            <h2>Chat Room: {room}</h2>
            <ul>
                {messages.map((msg, idx) => (
                    <li key={idx}>{JSON.stringify(msg)}</li>
                ))}
            </ul>
                <input type="text" value={msg} onChange={(e) => setMessages(e.target.value)} />
        </div>
    );
};

export default Chat;
